  const html="<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='theme-color' content='#07111f'><meta name='msapplication-TileColor' content='#07111f'><meta name='msapplication-TileImage' content='"+escapeHtml(image)+"'><meta name='description' content='"+escapeHtml(input.description)+"'><meta name='keywords' content='"+escapeHtml(input.keywords||"football predictions, football betting tips, accumulator tips, football odds, match analysis")+"'><meta name='robots' content='"+escapeHtml(input.robots||"index,follow,max-image-preview:large")+"'><link rel='canonical' href='"+escapeHtml(canonical)+"'><link rel='icon' href='/favicon.ico' sizes='any'><link rel='icon' type='image/svg+xml' href='/favicon.svg'><link rel='apple-touch-icon' href='/apple-touch-icon.png'><link rel='manifest' href='/site.webmanifest'><meta property='og:type' content='website'><meta property='og:site_name' content='AccaForge'><meta property='og:locale' content='en_KE'><meta property='og:title' content='"+escapeHtml(input.title)+"'><meta property='og:description' content='"+escapeHtml(input.description)+"'><meta property='og:url' content='"+escapeHtml(canonical)+"'><meta property='og:image' content='"+escapeHtml(image)+"'><meta property='og:image:type' content='image/png'><meta property='og:image:width' content='512'><meta property='og:image:height' content='512'><meta property='og:image:alt' content='AccaForge football predictions, odds analysis and match results'><meta name='twitter:card' content='summary_large_image'><meta name='twitter:url' content='"+escapeHtml(canonical)+"'><meta name='twitter:title' content='"+escapeHtml(input.title)+"'><meta name='twitter:description' content='"+escapeHtml(input.description)+"'><meta name='twitter:image' content='"+escapeHtml(image)+"'><meta name='twitter:image:alt' content='AccaForge football predictions, odds analysis and match results'><link rel='preconnect' href='https://fonts.googleapis.com'><link rel='preconnect' href='https://fonts.gstatic.com' crossorigin><link href='https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600&family=DM+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap' rel='stylesheet'><title>"+escapeHtml(input.title)+"</title><script type='application/ld+json'>"+safeJson(schema)+"</script><style>"+siteStyles+"</style></head><body><header class='top'><div class='shell topin'><a class='brand' href='/'>Acca<span>Forge</span></a><nav class='desktop-nav' aria-label='Main navigation'><a href='/'>Home</a><a href='/daily'>Daily board</a><a href='/recent'>Recent editions</a><a href='/competitions'>Competitions</a><a href='/football-betting-tips'>Guides</a></nav></div></header><nav class='mobile-dock' aria-label='Main mobile navigation'><a href='/'>Home</a><a href='/daily'>Daily</a><a href='/recent'>Archive</a><a href='/competitions'>Leagues</a></nav><main class='shell'><div class='crumb'><a href='/'>Home</a> / "+escapeHtml(input.title.split("|")[0].trim())+"</div>"+input.body+"</main><div class='shell'>"+footer+"</div></body></html>";
  return new Response(html,{status,headers:{"Content-Type":"text/html; charset=utf-8","Cache-Control":status===200?"public, max-age=0, s-maxage=120, stale-while-revalidate=300":"public, max-age=60","X-Content-Type-Options":"nosniff","Referrer-Policy":"strict-origin-when-cross-origin"}});
